#!/bin/sh
apply_service_profile(){ p=$1; case $p in minimal) replace_block "$CURRENT_HOME/.profile" performance 'export MAKEFLAGS=-j1\nexport CMAKE_BUILD_PARALLEL_LEVEL=1\nexport CARGO_BUILD_JOBS=1\nexport HISTSIZE=500\nexport HISTFILESIZE=500';; developer) pkg_install git curl wget make cmake ninja-build gcc g++ python3 python3-pip rust cargo nodejs npm go 2>/dev/null || true;; server) pkg_install openssh-server cron logrotate rsyslog curl;; ssh-only) pkg_install openssh-server; service_restart sshd 2>/dev/null || service_restart ssh 2>/dev/null || true;; rootfs) pkg_install debootstrap tar xz-utils zstd qemu-user-static binfmt-support 2>/dev/null || true;; aok) terminal_profile_apply compatible; build_profile size;; esac; }
profiles_bundles_menu(){ while :; do c=$(ui_menu 'Profiles and package bundles' 'Apply coherent presets or install tool collections.' profile 'Apply system profile' dev 'Development bundle' sysadmin 'System administration bundle' network 'Network administration bundle' terminal 'Terminal utilities bundle' monitoring 'Monitoring bundle' rootfs 'RootFS builder bundle' export 'Export current package list' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in profile) p=$(ui_menu Profile 'Select profile.' minimal Minimal developer Developer server Server ssh-only SSH-only rootfs 'RootFS builder' aok 'iSH-AOK optimized') || continue; apply_service_profile "$p";; dev) pkg_install git make cmake ninja-build meson gcc g++ clang gdb strace python3 python3-pip rust cargo nodejs npm go;; sysadmin) pkg_install procps util-linux coreutils findutils grep sed gawk rsync tmux screen htop lsof file tree;; network) pkg_install curl wget openssh-client iproute2 iputils-ping bind9-dnsutils netcat-openbsd tcpdump traceroute mtr openssl;; terminal) pkg_install bash-completion fzf ripgrep fd-find bat eza jq yq nnn lf ranger mc;; monitoring) pkg_install htop btop iotop iftop nmon sysstat lsof;; rootfs) pkg_install debootstrap qemu-user-static binfmt-support tar xz-utils zstd rsync;; export) package_list_all >"$REPORT_DIR/packages-$(date +%Y%m%d).txt"; ui_msg Export "Saved package list in $REPORT_DIR";; back) return;; esac; done; }
